623	fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
624	    // Inputs and the receipt destination are checked before the first effect; a provider failure
625	    // mid-run still leaves landed effects without a receipt, and a rerun adopts them.
626	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::ReleaseExecuteDryRun)?;
627	    let intent = read_intent(&args.intent)?;
628	    let orchestration_revision = callisto_model::CommitSha::parse(&args.orchestration_revision).map_err(|error| {
629	        CliError::ReleaseOrchestrationRevisionInvalid {
630	            revision: args.orchestration_revision.clone(),
631	            detail: error.to_string(),
632	        }
633	    })?;
634	    callisto_model::atomic::probe_atomic_write(&args.receipt, &permit).map_err(|source| CliError::Io {
635	        source,
636	        path: Some(args.receipt.clone()),
637	    })?;
638	    let manifest = args
639	        .artifact_manifest
640	        .as_deref()
641	        .map(read_artifact_manifest)
642	        .transpose()?;
643	    let sealed_python = manifest
644	        .as_ref()
645	        .is_some_and(|manifest| !manifest.distributions.is_empty());
646	    let needs_artifacts = sealed_python || !intent.artifact_slots.is_empty();
647	    let verified_artifacts = match (manifest.as_ref(), args.artifact_dir.as_deref()) {
648	        (None, None) if !needs_artifacts => None,
649	        (Some(manifest), Some(directory)) if needs_artifacts => {
650	            let runner = CliCommandRunner;
651	            Some(verify_artifact_manifest(&intent, manifest, directory, &runner)?)
652	        }
653	        _ if needs_artifacts => return Err(CliError::ReleaseMissingArtifactInputs),
654	        _ => return Err(CliError::ReleaseUnexpectedArtifactInputs),
655	    };
656	    // The run envelope is minted and cross-checked here, before the first
657	    // effect, and is then the single authority for every fact it carries.
658	    let envelope = ReleaseRunEnvelopeV1::new(
659	        orchestration_revision,
660	        &intent,
661	        verified_artifacts
662	            .as_ref()
663	            .map(|artifacts| artifacts.manifest().digest()),
664	    )
665	    .map_err(|error| CliError::ReleaseEnvelopeInvalid {
666	        detail: error.to_string(),
667	    })?;
668	    let runner = CliCommandRunner;
669	    let source_global = source_global(global, args.source_root.as_deref());
670	    let source_workspace = load_workspace(&source_global, &runner)?;
671	    // A missing forge-repository is the graph's error during intent validation; only the match lives here.
672	    if let Some(configured) = source_workspace
673	        .config
674	        .product_release
675	        .as_ref()
676	        .and_then(|release| release.forge_repository.as_ref())
677	        && let Some(slot) = intent
678	            .artifact_slots
679	            .iter()
680	            .find(|slot| slot.attestation_policy.repository != *configured)
681	    {
682	        return Err(CliError::ReleaseForgeRepositoryMismatch {
683	            configured: configured.as_slug(),
684	            requested: slot.attestation_policy.repository.as_slug(),
685	        });
686	    }
687	    // The workspace root, resolved exactly as `plan` resolves it. Executing
688	    // from a subdirectory must reach the same root, not the process cwd.
689	    let root = source_workspace.root.clone();
690	    let locator = IgnoreWalkLocator::new(&root);
691	    let capability = validate_release_intent(&root, &locator, &runner, intent)?;
692	    let state = execute_release(&capability, &permit, &envelope, verified_artifacts.as_ref())?;
693	    let receipt =
694	        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
695	            detail: error.to_string(),
696	        })?;
697	    write_receipt(&args.receipt, &receipt, &permit)?;
698	    match global.format {
699	        OutputFormat::Json => emit_report(
700	            &mut std::io::stdout(),
701	            &ReleaseExecuteReport {
702	                receipt: receipt.clone(),
703	            },
704	            global.dry_run,
705	        )?,
706	        OutputFormat::Text => emit_line(&format!("Release receipt saved to {}", args.receipt.display()))?,
707	    }
708	    Ok(ExitCode::SUCCESS)
709	}
