897	        assert!(text.contains('\u{2502}'), "expected a box-drawing char in:\n{text}");
898	        for entry in &intent.decision.entries {
899	            assert!(text.contains(&entry.package.to_string()), "{text}");
900	        }
901	    }
902	
903	    /// `use_color: false` never emits box-drawing characters.
904	    #[test]
905	    fn plan_text_without_color_has_no_box_drawing_chars() {
