181	struct OpIndex {
182	    publishes_by_package: BTreeMap<ReleasePackageId, Vec<ReleaseOperationId>>,
183	    /// Owner registry publish -> its platform publishes, which must land first.
184	    platforms_by_publish: BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
185	    tag_by_package: BTreeMap<ReleasePackageId, ReleaseOperationId>,
186	    forge_by_package: BTreeMap<ReleasePackageId, ReleaseOperationId>,
187	    /// Keyed by the product's id: a plugin-built asset must still gate the product's own forge-publish.
188	    uploads_by_package: BTreeMap<ReleasePackageId, Vec<ReleaseOperationId>>,
189	    /// Keyed by the product's id: the tag of each other package whose asset the product's release carries, which
190	    /// follows that package's registry publishes, so the announcement waits for them too.
191	    asset_owner_tags_by_package: BTreeMap<ReleasePackageId, BTreeSet<ReleaseOperationId>>,
192	}
193	
194	impl OpIndex {
195	    /// The registry publishes a package's tag waits for: those of every release identity of the package, since a
196	    /// dual Cargo and npm owner has one physical tag but a publish per manifest.
197	    fn tag_prerequisites(&self, owners: &[ReleasePackageId]) -> Vec<ReleaseOperationId> {
198	        let publishes: BTreeSet<_> = owners
199	            .iter()
200	            .flat_map(|owner| self.publishes_by_package.get(owner).into_iter().flatten().cloned())
201	            .collect();
202	        publishes.into_iter().collect()
203	    }
204	}
