206	fn derive_release_inputs_with<R: CommandRunner, D: DependencyResolver>(
207	    workspace: &Workspace<'_, R, D>,
208	    decision: &ReleaseDecisionV1,
209	    source: SourceIdentity,
210	    artifact_policy: Option<&ArtifactBuildPolicy>,
211	    remote: GitRemoteRequirement,
212	    diagnostics: &mut Vec<Diagnostic>,
213	) -> Result<DerivedReleaseInputs, GraphError> {
214	    if workspace
215	        .config
216	        .product_release
217	        .as_ref()
218	        .is_some_and(|release| release.forge_repository.is_none())
219	    {
220	        return Err(GraphError::ReleaseForgeRepositoryMissing);
221	    }
222	    let mut package_inputs = Vec::new();
223	    let Selection {
224	        selected,
225	        package_ids,
226	        owners,
227	    } = select_packages(workspace, decision)?;
228	    require_dependencies_selected(workspace, &selected, &package_ids)?;
229	    let all_packages: Vec<_> = workspace.graph.packages().map(|package| package.id.clone()).collect();
230	    let publish_edges = PublishEdgeFilter::new(
231	        &package_ids.keys().cloned().collect(),
232	        &all_packages,
233	        |id: &callisto_model::PackageId| {
234	            workspace
235	                .graph
236	                .dependencies_of(id)
237	                .map(|edge| (edge.to.clone(), edge.kind))
238	                .collect()
239	        },
240	    )?;
241	
