    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
    git_remote: Option<&PreparedGitRemote>,
    package_inputs: &mut Vec<ReleasePackageInputV1>,
    ops: &mut Ops,

