pub struct ProductArtifactConfig {
    /// The package whose build produces these bytes. Need not be the product.
    pub package: PackageId,
    pub target: String,
    pub asset_name: String,
}

/// Both `product-package` and every `[[release.artifact]] package` must name one
/// ecosystem-qualified identity; one parser so the two cannot drift.
fn parse_qualified_package(value: &str, key: &str) -> Result<PackageId, ConfigError> {
    ConfigError::require_qualified(value, key)?;
    PackageId::parse(value).map_err(|_error| ConfigError::InvalidProductRelease {
        detail: format!("{key} must be an ecosystem-qualified package identity"),
    })
}

fn resolve_product_release(raw: RawProductReleaseConfig) -> Result<ProductReleaseConfig, ConfigError> {
    let package = parse_qualified_package(&raw.product_package, "product-package")?;
    if raw.artifact.is_empty() {
        return Err(ConfigError::InvalidProductRelease {
            detail: "a [release] section must declare at least one [[release.artifact]]".to_owned(),
        });
    }
    let mut artifacts = Vec::with_capacity(raw.artifact.len());
    let mut seen_assets = BTreeSet::new();
    for entry in &raw.artifact {
        let package = parse_qualified_package(&entry.package, "[[release.artifact]] package")?;
        if !is_safe_artifact_component(&entry.target) || !is_safe_artifact_component(&entry.asset_name) {
            return Err(ConfigError::InvalidProductRelease {
                detail: format!(
                    "artifact target `{}` and asset-name `{}` must each be a single safe path component",
                    entry.target, entry.asset_name
                ),
            });
        }
        if !seen_assets.insert(entry.asset_name.clone()) {
            return Err(ConfigError::InvalidProductRelease {
                detail: format!("asset-name `{}` is declared more than once", entry.asset_name),
            });
        }
        artifacts.push(ProductArtifactConfig {
    const ARTIFACT: &str =
        "\n[[release.artifact]]\npackage = \"cargo/demo\"\ntarget = \"aarch64-apple-darwin\"\nasset-name = \"demo.tar.gz\"\n";

    fn resolve_str(body: &str) -> Result<ResolvedConfig, ConfigError> {
        let raw = toml::from_str::<RawConfig>(&format!("{RELEASE_HEAD}{body}{ARTIFACT}")).expect("parse");
        resolve(Path::new("/workspace"), raw)
    }

    fn forge(config: &ResolvedConfig) -> Option<String> {
        config
            .product_release
            .as_ref()
            .and_then(|release| release.forge_repository.as_ref())
            .map(GitHubRepository::as_slug)
    }

    fn detail(result: Result<ResolvedConfig, ConfigError>) -> String {
        match result {
            Err(ConfigError::InvalidProductRelease { detail }) => detail,
            other => panic!("expected InvalidProductRelease, got {:?}", other.map(|_| ())),
        }
    }

    #[test]
    fn top_level_forge_repository_resolves() {
        let config = resolve_str("forge-repository = \"orin-dx/callisto\"\n").unwrap();
        assert_eq!(forge(&config).as_deref(), Some("orin-dx/callisto"));
    }

    /// The removed `[release.profiles]` and `[init]` tables are unknown keys now, not silently accepted.
    #[test]
    fn removed_legacy_tables_are_rejected() {
        for body in [
            "[release.profiles.production]\nforge-repository = \"orin-dx/legacy\"\n",
            "[init]\necosystems = [\"cargo\"]\n",
        ] {
            assert!(toml::from_str::<RawConfig>(body).is_err(), "{body}");
        }
    }

    #[test]
    fn an_invalid_forge_repository_is_rejected() {
        assert!(detail(resolve_str("forge-repository = \"not a repo\"\n")).contains("not a repo"));
    }

    #[test]
    fn load_is_read_parse_then_resolve() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let content = format!(
            "{RELEASE_HEAD}forge-repository = \"orin-dx/callisto\"\n{ARTIFACT}\n[cascade]\nmode = \"always\"\n\n[registries.corp]\nkind = \"cargo\"\nurl = \"https://corp.example/index\"\n\n[[package]]\nmatch = \"cargo/demo\"\npublish-to = [\"crates-io\"]\n"
        );
use std::fs;

const HEAD: &str = "[release]\nproduct-package = \"cargo/demo\"\n\n[[release.artifact]]\npackage = \"cargo/demo\"\ntarget = \"aarch64-apple-darwin\"\nasset-name = \"callisto-aarch64-apple-darwin.tar.gz\"\n\n[[release.artifact]]\npackage = \"cargo/demo\"\ntarget = \"x86_64-unknown-linux-gnu\"\nasset-name = \"callisto-x86_64-unknown-linux-gnu.tar.gz\"\n\n[[release.artifact]]\npackage = \"cargo/demo\"\ntarget = \"x86_64-unknown-linux-musl\"\nasset-name = \"callisto-x86_64-unknown-linux-musl.tar.gz\"\n\n[[release.artifact]]\npackage = \"cargo/demo\"\ntarget = \"wasm32-wasip1\"\nasset-name = \"callisto-moon.wasm\"\n";

fn load(body: &str) -> Result<callisto_graph::ResolvedConfig, callisto_graph::error::ConfigError> {
    let d = tempfile::tempdir().unwrap();
    fs::write(d.path().join("callisto.toml"), format!("{HEAD}{body}")).unwrap();
    load_config_at(d.path())
}
fn load_config_at(p: &std::path::Path) -> Result<callisto_graph::ResolvedConfig, callisto_graph::error::ConfigError> {
    callisto_graph::load_config(p)
}

fn artifact(package: &str, target: &str, asset: &str) -> String {
    format!("[[release.artifact]]\npackage = \"{package}\"\ntarget = \"{target}\"\nasset-name = \"{asset}\"\n")
}
fn release(artifacts: &str) -> String {
    format!("[release]\nproduct-package = \"cargo/demo\"\n{artifacts}")
}

/// No product identity is compiled in: any workspace may ship any targets under any names.
#[test]
fn a_non_callisto_product_with_its_own_targets_loads() {
    let d = tempfile::tempdir().unwrap();
    let body = release(
        &(artifact("cargo/demo", "x86_64-pc-windows-msvc", "demo-windows.zip")
            + &artifact("cargo/demo", "riscv64gc-unknown-linux-gnu", "demo-riscv.tar.gz")),
    );
    fs::write(d.path().join("callisto.toml"), body).unwrap();
    let config = load_config_at(d.path()).expect("generic artifact config loads");
    let assets: Vec<_> = config
        .product_release
        .unwrap()
        .artifacts
        .into_iter()
        .map(|a| a.asset_name)
        .collect();
    assert_eq!(assets, ["demo-windows.zip", "demo-riscv.tar.gz"]);
}

#[test]
fn invalid_artifact_declarations_are_rejected() {
    let d = tempfile::tempdir().unwrap();
    let cases = [
        ("empty", release("")),
        (
            "duplicate asset",
            release(&(artifact("cargo/demo", "a", "same.tar.gz") + &artifact("cargo/demo", "b", "same.tar.gz"))),
